// Independent whole score-page renders from original Audiveris font resources.
import java.awt.*;import java.awt.image.*;import java.nio.file.*;import java.lang.reflect.*;import java.util.*;
public class HeadActualPageRenderer {
 static Class<?> cls(String s)throws Exception{return Class.forName("org.audiveris.omr."+s);}
 static Object call(Object o,String name,Object... a)throws Exception {for(Method m:(o instanceof Class<?>?(Class<?>)o:o.getClass()).getMethods())if(m.getName().equals(name)&&m.getParameterCount()==a.length){boolean ok=true;Class<?>[]t=m.getParameterTypes();for(int i=0;i<t.length;i++)if(a[i]!=null&&!t[i].isInstance(a[i])&&!(t[i]==int.class&&a[i] instanceof Integer)&&!(t[i]==boolean.class&&a[i] instanceof Boolean))ok=false;if(ok)return m.invoke(o instanceof Class<?>?null:o,a);}throw new NoSuchMethodException(name);}
 static BufferedImage symbol(String family,String shape,int point)throws Exception{Object f=cls("ui.symbol.MusicFamily").getField(family).get(null),font=call(cls("ui.symbol.MusicFont"),"getMusicFont",f,point),s=cls("glyph.Shape").getField(shape).get(null);if(shape.startsWith("NOTEHEAD")||shape.startsWith("WHOLE_NOTE")||shape.startsWith("BREVE")){Object sym=cls("ui.symbol.TemplateSymbol").getConstructor(cls("glyph.Shape"),cls("ui.symbol.MusicFamily")).newInstance(s,f);return (BufferedImage)call(sym,"buildImage",font);}java.awt.font.TextLayout layout=(java.awt.font.TextLayout)call(font,"layoutShapeByCode",s);java.awt.geom.Rectangle2D b=layout.getBounds();BufferedImage image=new BufferedImage((int)Math.ceil(b.getWidth())+2,(int)Math.ceil(b.getHeight())+2,BufferedImage.TYPE_INT_ARGB);Graphics2D g=image.createGraphics();g.setColor(Color.BLACK);g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);layout.draw(g,(float)(1-b.getX()),(float)(1-b.getY()));g.dispose();return image;}
 static void stamp(BufferedImage page,BufferedImage glyph,int x,int cy){int oy=cy-glyph.getHeight()/2;for(int y=0;y<glyph.getHeight();y++)for(int xx=0;xx<glyph.getWidth();xx++){int c=glyph.getRGB(xx,y),px=x+xx,py=oy+y;if((c>>>24)>=140&&((c>>16)&255)<140&&px>=0&&px<page.getWidth()&&py>=0&&py<page.getHeight())page.getRaster().setSample(px,py,0,0);}}
 public static void main(String[] a)throws Exception {Path out=Path.of(a[0]);Files.createDirectories(out);call(cls("ui.symbol.MusicFont"),"populateAllSymbols");for(String[] cfg:new String[][]{{"Bravura","five"},{"Leland","five"},{"FinaleJazz","five"},{"Bravura","one-drum"},{"Bravura","five-drum"},{"Bravura","six-tab"},{"Bravura","cue"}}){String fam=cfg[0],mode=cfg[1];BufferedImage page=new BufferedImage(1280,720,BufferedImage.TYPE_BYTE_GRAY);Graphics2D g=page.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,1280,720);g.setColor(Color.BLACK);
  for(int staff=0;staff<(mode.equals("cue")?4:2);staff++){int top=mode.equals("cue")?150+150*staff:staff==0?220:450,il=staff==0&&mode.equals("cue")?7:11,point=il==7?32:51,lines=staff==0?(mode.equals("one-drum")?1:mode.equals("six-tab")?6:5):5;for(int i=0;i<lines;i++)g.fillRect(80,top+i*il,1120,2);g.fillRect(80,top,2,(lines-1)*il+2);g.fillRect(1198,top,2,(lines-1)*il+2);
   String clef=staff==0&&mode.contains("drum")?"PERCUSSION_CLEF":staff==0&&mode.equals("six-tab")?"G_CLEF":"G_CLEF";stamp(page,symbol(fam,clef,point),100,top+(lines-1)*il/2);stamp(page,symbol(fam,"TIME_FOUR",point),165,top+il);stamp(page,symbol(fam,"TIME_FOUR",point),165,top+3*il);
   String[] shapes=staff==0&&mode.contains("drum")?new String[]{"NOTEHEAD_CROSS","NOTEHEAD_DIAMOND_FILLED","NOTEHEAD_TRIANGLE_DOWN_FILLED","NOTEHEAD_CIRCLE_X","NOTEHEAD_CROSS_VOID","NOTEHEAD_DIAMOND_VOID","WHOLE_NOTE_CROSS","BREVE_CROSS"}:new String[]{"NOTEHEAD_BLACK","NOTEHEAD_VOID","NOTEHEAD_BLACK","NOTEHEAD_VOID","NOTEHEAD_BLACK_SMALL","NOTEHEAD_VOID_SMALL","WHOLE_NOTE","BREVE"};
   int[] pitch={-4,-2,0,2,4,-1,1,3};for(int i=0;i<8;i++){int x=270+120*i,cy=top+((lines-1)*il)/2+(pitch[i]*il)/2;BufferedImage image=symbol(fam,shapes[i],point);stamp(page,image,x,cy);if(i<6)g.fillRect(x+image.getWidth()-2,cy-36,2,37);}
  }g.dispose();javax.imageio.ImageIO.write(page,"PNG",out.resolve(fam+"-"+mode+".png").toFile());
 }
 }
}
